		company := lead.CompanyName
		receipts = append(receipts, schema.CreateFollowupReminderReceipt{
			DeduplicationKey: keys[index], LeadID: schema.NewFollowupReminderReceiptLeadIDReference(lead.ID),
			RecipientUserID: schema.NewFollowupReminderReceiptRecipientUserIDReference(schema.IdentityUserID(principal.UserID)), ReminderDate: day,
