			SubjectObjectKey: "lead", SubjectRecordID: string(lead.ID), SubjectVersion: lead.UpdatedAt,
			DedupeKey: "followup-overdue:" + keys[index], GroupKey: "lead:" + string(lead.ID), OccurredAt: now,
			Variables: []capabilities.SendOverdueRemindersNotificationVariable{{Key: "company_name", StringValue: &company}},
