)

// ApproveConversion implements the project-owned lead.approve_conversion Handler.
func ApproveConversion(ctx context.Context, caps capabilities.ApproveConversionCapabilities, input capabilities.ApproveConversionInput) (capabilities.ApproveConversionOutput, error) {
	_ = input
	if caps.Execution == nil || caps.Lead == nil || caps.Customer == nil || caps.Notifications == nil {
		return capabilities.ApproveConversionOutput{}, businessError("lead.approve_conversion.capability_unavailable")
	}
	lead, err := caps.Lead.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}
	if string(lead.Status) != "qualified" {
		return capabilities.ApproveConversionOutput{}, businessError("lead.approve_conversion.invalid_state")
	}
	comparison, err := amountCompare(lead.ExpectedAmount, conversionThreshold)
	if err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}
	if comparison < 0 {
		return capabilities.ApproveConversionOutput{}, businessError("lead.approve_conversion.threshold_not_met")
	}
	mutation := data.NewLeadUpdate(lead.ID).SetStatus(schema.LeadStatus("converted")).SetStatusChangedAt(time.Now().UTC()).RequireStatusEqual(lead.Status, "lead.approve_conversion.conflict")
	updated, err := caps.Lead.ConditionalUpdate(ctx, mutation)
	if err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}
	if _, err = caps.Customer.Create(ctx, schema.CreateCustomer{Amount: schema.CustomerAmount(lead.ExpectedAmount), CompanyName: lead.CompanyName, ContactName: lead.ContactName, SourceLeadID: schema.NewCustomerSourceLeadIDReference(lead.ID)}); err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}
	company := lead.CompanyName
	principal := caps.Execution.Principal()
	_, err = caps.Notifications.Dispatch(ctx, capabilities.ApproveConversionNotificationIntent{
		EventType: "lead.conversion_approved", SourceEventID: "lead-approval-approved:" + string(lead.ID), RecipientUserIDs: []string{principal.UserID},
		SubjectObjectKey: "lead", SubjectRecordID: string(lead.ID), SubjectVersion: updated.UpdatedAt,
		DedupeKey: "lead-approval-approved:" + string(lead.ID), GroupKey: "lead:" + string(lead.ID), OccurredAt: time.Now().UTC(),
		Variables: []capabilities.ApproveConversionNotificationVariable{{Key: "company_name", StringValue: &company}},
	})
	if err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}
	return capabilities.ApproveConversionOutput{}, nil
}
