	}
	comparison, err := amountCompare(lead.ExpectedAmount, conversionThreshold)
	if err != nil {
		return capabilities.PrepareApprovalOutput{}, err
	}
	if comparison < 0 {
		return capabilities.PrepareApprovalOutput{}, businessError("lead.prepare_approval.not_required")
	}
	requestID := schema.LeadConversionRequestID(lead.ID)
	if _, found, err := caps.LeadConversionRequest.Optional(ctx, requestID); err != nil {
		return capabilities.PrepareApprovalOutput{}, err
	} else if found {
		return capabilities.PrepareApprovalOutput{}, nil
	}
	_, err = caps.LeadConversionRequest.Create(ctx, schema.CreateLeadConversionRequest{
		LeadID:         schema.NewLeadConversionRequestLeadIDReference(lead.ID),
		AmountSnapshot: schema.LeadConversionRequestAmountSnapshot(lead.ExpectedAmount),
		Status:         schema.LeadConversionRequestStatus("pending"),
	})
	if err != nil {
