// RejectConversion implements the project-owned lead.reject_conversion Handler.
func RejectConversion(ctx context.Context, caps capabilities.RejectConversionCapabilities, input capabilities.RejectConversionInput) (capabilities.RejectConversionOutput, error) {
	if caps.Execution == nil || caps.Lead == nil || caps.LeadConversionRequest == nil || caps.Notifications == nil {
		return capabilities.RejectConversionOutput{}, businessError("lead.reject_conversion.capability_unavailable")
	}
	if input.RejectionReason == "" {
		return capabilities.RejectConversionOutput{}, businessError("lead.reject_conversion.reason_required")
	}
	lead, err := caps.Lead.GetForUpdate(ctx, caps.Execution.TargetID())
	if err != nil {
		return capabilities.RejectConversionOutput{}, err
	}
	if string(lead.Status) != "qualified" {
		return capabilities.RejectConversionOutput{}, businessError("lead.reject_conversion.invalid_state")
	}
	request, err := caps.LeadConversionRequest.GetForUpdate(ctx, schema.LeadConversionRequestID(lead.ID))
	if err != nil {
		return capabilities.RejectConversionOutput{}, err
	}
	now := time.Now().UTC()
	mutation := data.NewLeadConversionRequestUpdate(request.ID).
		SetStatus(schema.LeadConversionRequestStatus("rejected")).SetRejectionReason(input.RejectionReason).SetDecidedAt(now).
		RequireStatusEqual(request.Status, "lead.reject_conversion.conflict")
	updated, err := caps.LeadConversionRequest.ConditionalUpdate(ctx, mutation)
	if err != nil {
		return capabilities.RejectConversionOutput{}, err
	}
	company, reason := lead.CompanyName, input.RejectionReason
	principal := caps.Execution.Principal()
	_, err = caps.Notifications.Dispatch(ctx, capabilities.RejectConversionNotificationIntent{
		EventType: "lead.conversion_rejected", SourceEventID: "lead-approval-rejected:" + string(lead.ID), RecipientUserIDs: []string{principal.UserID},
		SubjectObjectKey: "lead_conversion_request", SubjectRecordID: string(request.ID), SubjectVersion: updated.UpdatedAt,
		DedupeKey: "lead-approval-rejected:" + string(lead.ID), GroupKey: "lead:" + string(lead.ID), OccurredAt: now,
		Variables: []capabilities.RejectConversionNotificationVariable{{Key: "company_name", StringValue: &company}, {Key: "rejection_reason", StringValue: &reason}},
	})
	if err != nil {
		return capabilities.RejectConversionOutput{}, err
	}
	return capabilities.RejectConversionOutput{}, nil
}
