const conversionThreshold = "100000.00"

func businessError(code string) error {
	return &capabilities.BusinessError{Code: code}
}

func amountCompare(amount schema.LeadExpectedAmount, threshold string) (int, error) {
	left, ok := new(big.Rat).SetString(string(amount))
	if !ok {
		return 0, businessError("lead.expected_amount.invalid")
	}
	right, ok := new(big.Rat).SetString(threshold)
	if !ok {
		return 0, businessError("lead.conversion_threshold.invalid")
	}
	return left.Cmp(right), nil
}

func mutableLeadStatus(status schema.LeadStatus) bool {
	switch string(status) {
	case "new", "contacted", "qualified":
		return true
	default:
		return false
	}
}

