		return
	}
	req.IdempotencyKey = key
	result, err := h.actions.ExecuteBulkAction(r.Context(), strings.TrimSpace(r.PathValue("objectKey")), strings.TrimSpace(r.PathValue("actionKey")), req, h.principal(r))
