	f := &runtimeFixture{baseURL: baseURL, workspace: workspace, appKey: appKey, phase: phase, management: management}
	users := []struct {
		id, name, org, role string
		target              *runtimeClient
	}{
		{"bf-sales-east", "华东销售", "bf-east", "sales_rep", &f.east},
		{"bf-sales-east-peer", "华东同事", "bf-east", "sales_rep", &f.eastPeer},
		{"bf-sales-west", "华北销售", "bf-west", "sales_rep", &f.west},
		{"bf-sales-director", "销售总监", "bf-east", "sales_director", &f.director},
	}
	for _, item := range users {
		password := ""
		status, _, _ := management.request(http.MethodGet, "/identity/users/"+item.id, nil, nil)
		if status == http.StatusNotFound {
			payload := map[string]any{"id": item.id, "name": item.name, "email": item.id + "@example.invalid", "account_type": "human", "locale": "zh_CN", "timezone": "Asia/Shanghai", "org_id": item.org, "reporting_path": "/" + item.org + "/" + item.id, "status": "active"}
			var created any
			status, created, _ = management.request(http.MethodPost, "/identity/users", payload, nil)
			if status != http.StatusCreated {
				return nil, fmt.Errorf("user %s provisioning returned %d", item.id, status)
			}
			password = deepString(created, "initial_password")
		}
		if status != http.StatusOK && status != http.StatusCreated {
			return nil, fmt.Errorf("user %s lookup returned %d", item.id, status)
		}
		assignment := map[string]any{"role_id": roles[item.role], "grant_reason": "M1 business-flow verification"}
		status, _, _ = management.request(http.MethodPost, "/identity/users/"+item.id+"/role-assignments", assignment, authoringHeaders("bf-role-"+item.id, "empty"))
		if status != http.StatusOK && status != http.StatusCreated {
			return nil, fmt.Errorf("role assignment for %s returned %d", item.id, status)
		}
		client, loginErr := authenticate(baseURL, workspace, appKey, item.id, changedPassword)
		if loginErr != nil && password != "" {
			client, loginErr = authenticate(baseURL, workspace, appKey, item.id, password)
			if loginErr == nil {
				client, loginErr = changePassword(client, password, changedPassword, "bf-user-password-"+item.id)
			}
		}
		if loginErr != nil {
			return nil, fmt.Errorf("business user %s login failed", item.id)
		}
		client.userID, client.roleKey = item.id, item.role
		*item.target = client
	}
	return f, nil
}

func authenticate(baseURL, workspace, appKey, login, password string) (runtimeClient, error) {
	c := runtimeClient{baseURL: baseURL}
	status, body, _ := c.request(http.MethodPost, "/auth/login", map[string]any{"workspace_id": workspace, "application_key": appKey, "login": login, "password": password}, nil)
	if status != http.StatusOK {
		return runtimeClient{}, fmt.Errorf("login returned %d", status)
	}
	token := deepString(body, "access_token")
	if token == "" {
		return runtimeClient{}, errors.New("login response omitted access token")
	}
	c.token = token
	return c, nil
}

func changePassword(c runtimeClient, current, next, key string) (runtimeClient, error) {
	status, body, _ := c.request(http.MethodPost, "/auth/change-password", map[string]any{"current_password": current, "new_password": next}, map[string]string{"Idempotency-Key": key})
	if status != http.StatusOK {
		return runtimeClient{}, fmt.Errorf("password change returned %d", status)
	}
	token := deepString(body, "access_token")
	if token == "" {
		return runtimeClient{}, errors.New("password change omitted reissued session")
	}
	c.token = token
	return c, nil
}

func authoringHeaders(key, expected string) map[string]string {
	return map[string]string{"Builder-Task-ID": "DB-M1-CRM-BASELINE", "Idempotency-Key": key, "Expected-Schema-Hash": expected}
}

func (c runtimeClient) request(method, path string, payload any, headers map[string]string) (int, any, http.Header) {
	var body io.Reader
	if payload != nil {
		encoded, _ := json.Marshal(payload)
		body = bytes.NewReader(encoded)
	}
	req, err := http.NewRequest(method, c.baseURL+path, body)
	if err != nil {
		return 0, map[string]any{"client_error": err.Error()}, nil
	}
	if payload != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if c.token != "" {
		req.Header.Set("Authorization", "Bearer "+c.token)
	}
	req.Header.Set("X-Request-ID", "bf-"+fmt.Sprint(time.Now().UnixNano()))
	for key, value := range headers {
		req.Header.Set(key, value)
	}
	response, err := http.DefaultClient.Do(req)
	if err != nil {
		return 0, map[string]any{"client_error": err.Error()}, nil
	}
	defer response.Body.Close()
	raw, _ := io.ReadAll(io.LimitReader(response.Body, 4<<20))
	var decoded any
	if len(raw) != 0 && strings.Contains(response.Header.Get("Content-Type"), "json") {
		_ = json.Unmarshal(raw, &decoded)
	}
	if decoded == nil {
		decoded = raw
	}
	return response.StatusCode, decoded, response.Header.Clone()
}

func mustRequest(t *testing.T, c runtimeClient, method, path string, payload any, headers map[string]string, statuses ...int) (any, http.Header) {
	t.Helper()
	status, body, responseHeaders := c.request(method, path, payload, headers)
	for _, expected := range statuses {
		if status == expected {
			return body, responseHeaders
		}
	}
	t.Fatalf("%s %s returned %d: %s", method, path, status, compactJSON(body))
	return nil, nil
}

func actionKey(t *testing.T, c runtimeClient, objectKey, wanted string) string {
	t.Helper()
	body, _ := mustRequest(t, c, http.MethodGet, "/records/"+objectKey+"/actions", nil, nil, http.StatusOK)
	if deepHasString(body, "key", wanted) {
		return wanted
	}
	t.Fatalf("Runtime action catalog for %s does not expose %s", objectKey, wanted)
	return ""
}

func runObjectAction(t *testing.T, c runtimeClient, objectKey, wanted, idem string, data map[string]any) any {
