// BF03 / CRM-R06-R09,R13: the highest-risk path runs first. It proves the
// real Workflow/task boundary, unauthorized no-op, atomic terminal facts and
// the requester-owned durable notification.
func TestBF03ApprovalAccepted(t *testing.T) {
	f := fixture(t)
	leadID := qualifyLead(t, f, f.east, "BF03-大额通过-"+f.phase, "100000.00")
