}

// BF01 / CRM-R01-R05,R11,R13: create and replay one lead, edit and advance it
// as owner, then prove a same-department peer cannot mutate durable state.
func TestBF01LeadLifecycleAndScope(t *testing.T) {
	f := fixture(t)
	label := "BF01-线索生命周期-" + f.phase
	idem := "bf01-create-" + f.phase
	payload := map[string]any{"company_name": label, "contact_name": "甲", "contact_phone": "+8613900000001", "expected_amount": "888.88", "source": "trade_show"}
	first := runObjectAction(t, f.east, "lead", "lead.capture", idem, payload)
	second := runObjectAction(t, f.east, "lead", "lead.capture", idem, payload)
	leadID := createdRecordID(first, "lead")
	if leadID == "" {
		leadID = createdRecordID(second, "lead")
	}
	items := listRecords(t, f.east, "lead", 100, map[string]any{"company_name": label})
	if len(items) != 1 || (leadID != "" && recordID(items[0]) != leadID) {
		t.Fatalf("idempotent capture produced %d matching records", len(items))
	}
	leadID = recordID(items[0])
	runRecordAction(t, f.east, "lead", leadID, "lead.update_details", "bf01-update-"+f.phase, map[string]any{"contact_name": "乙", "contact_phone": "+8613900000002", "expected_amount": "999.99", "source": "referral"})
	runRecordAction(t, f.east, "lead", leadID, "lead.mark_contacted", "bf01-contact-"+f.phase, map[string]any{})
	beforeDenied := getRecord(t, f.east, "lead", leadID)
	status, _, _ := f.eastPeer.request(http.MethodPost, "/records/lead/items/"+leadID+"/actions/lead.qualify", map[string]any{"data": map[string]any{}}, map[string]string{"Idempotency-Key": "bf01-peer-denied-" + f.phase})
	if status != http.StatusForbidden {
		t.Fatalf("same-department non-owner write returned %d, want 403", status)
	}
	if compactJSON(beforeDenied) != compactJSON(getRecord(t, f.east, "lead", leadID)) {
		t.Fatalf("denied peer write changed durable state")
	}
	runRecordAction(t, f.east, "lead", leadID, "lead.qualify", "bf01-qualify-"+f.phase, map[string]any{})
	qualified := getRecord(t, f.east, "lead", leadID)
	if recordDataString(qualified, "status") != "qualified" || recordDataString(qualified, "contact_name") != "乙" || recordDataString(qualified, "expected_amount") != "999.99" {
		t.Fatalf("owner lifecycle read-back mismatch: %s", compactJSON(qualified))
	}
	status, _, _ = f.east.request(http.MethodPost, "/records/lead/items/"+leadID+"/actions/lead.mark_contacted", map[string]any{"data": map[string]any{}}, map[string]string{"Idempotency-Key": "bf01-illegal-" + f.phase})
	if status != http.StatusConflict && status != http.StatusBadRequest {
		t.Fatalf("illegal state regression returned %d", status)
	}
	if recordDataString(getRecord(t, f.east, "lead", leadID), "status") != "qualified" {
		t.Fatalf("illegal transition changed state")
	}
}

