func waitProcess(t *testing.T, actor runtimeClient, processID, wanted string) map[string]any {
	t.Helper()
	var process map[string]any
	waitFor(t, "workflow process "+wanted, func() bool {
		status, body, _ := actor.request(http.MethodGet, "/workflow/processes/"+processID, nil, nil)
		if status != http.StatusOK {
			return false
		}
		if detail, ok := body.(map[string]any); ok {
			if nested, ok := detail["process"].(map[string]any); ok {
				process = nested
			} else {
				process = detail
			}
		}
		return process != nil && fmt.Sprint(process["status"]) == wanted
	})
	return process
}

