func SendOverdueReminders(ctx context.Context, caps capabilities.SendOverdueRemindersCapabilities, input capabilities.SendOverdueRemindersInput) (capabilities.SendOverdueRemindersOutput, error) {
	_ = input
	if caps.Execution == nil || caps.Lead == nil || caps.FollowupReminderReceipt == nil || caps.Notifications == nil {
		return capabilities.SendOverdueRemindersOutput{}, businessError("lead.send_overdue_reminders.capability_unavailable")
	}
	now := time.Now().UTC()
	cutoff := now.Add(-7 * 24 * time.Hour)
	leads, err := caps.Lead.List(ctx, data.NewLeadQuery().
		WhereStatusEqual(schema.LeadStatus("contacted")).
		WhereStatusChangedAtLessThanOrEqual(cutoff).
		OrderByIDAscending().Page(1, 200))
	if err != nil {
		return capabilities.SendOverdueRemindersOutput{}, err
	}
	day := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC)
	queries := make([]data.FollowupReminderReceiptQuery, len(leads))
	keys := make([]string, len(leads))
	for index, lead := range leads {
		keys[index] = string(lead.ID) + ":" + day.Format("2006-01-02")
		queries[index] = data.NewFollowupReminderReceiptQuery().WhereDeduplicationKeyEqual(keys[index]).Page(1, 1)
	}
	exists, err := caps.FollowupReminderReceipt.ExistsBatch(ctx, queries)
	if err != nil {
		return capabilities.SendOverdueRemindersOutput{}, err
	}
	receipts := make([]schema.CreateFollowupReminderReceipt, 0, len(leads))
	intents := make([]capabilities.SendOverdueRemindersNotificationIntent, 0, len(leads))
	for index, lead := range leads {
		if exists[index] {
			continue
		}
		company := lead.CompanyName
		receipts = append(receipts, schema.CreateFollowupReminderReceipt{
			DeduplicationKey: keys[index], LeadID: schema.NewFollowupReminderReceiptLeadIDReference(lead.ID),
			RecipientUserID: schema.NewFollowupReminderReceiptRecipientUserIDReference(schema.IdentityUserID(lead.ResponsibleUserID)), ReminderDate: day,
		})
		intents = append(intents, capabilities.SendOverdueRemindersNotificationIntent{
			EventType: "lead.followup_overdue", SourceEventID: "followup-overdue:" + keys[index], RecipientUserIDs: []string{lead.ResponsibleUserID},
			SubjectObjectKey: "lead", SubjectRecordID: string(lead.ID), SubjectVersion: lead.UpdatedAt,
			DedupeKey: "followup-overdue:" + keys[index], GroupKey: "lead:" + string(lead.ID), OccurredAt: now,
			Variables: []capabilities.SendOverdueRemindersNotificationVariable{{Key: "company_name", StringValue: &company}},
		})
	}
	if len(receipts) == 0 {
		return capabilities.SendOverdueRemindersOutput{}, nil
	}
	if _, err = caps.FollowupReminderReceipt.CreateBatch(ctx, receipts); err != nil {
		return capabilities.SendOverdueRemindersOutput{}, err
	}
	if _, err = caps.Notifications.DispatchBatch(ctx, intents); err != nil {
		return capabilities.SendOverdueRemindersOutput{}, err
	}
	return capabilities.SendOverdueRemindersOutput{}, nil
}
