	result := runObjectAction(t, c, "lead", "lead.capture", idem, map[string]any{"company_name": label, "contact_name": "联系人", "contact_phone": "+8613800000000", "expected_amount": amount, "source": "website"})
	id := createdRecordID(result, "lead")
	if id == "" {
		items := listRecords(t, c, "lead", 100, map[string]any{"company_name": label})
		if len(items) != 1 {
			t.Fatalf("capture %s did not yield one durable lead", label)
		}
		id = recordID(items[0])
	}
	record := getRecord(t, c, "lead", id)
	if recordDataString(record, "company_name") != label || recordDataString(record, "responsible_user_id") != c.userID || recordDataString(record, "status") != "new" {
		t.Fatalf("captured lead read-back mismatch: %s", compactJSON(record))
	}
	return id
}

func qualifyLead(t *testing.T, f *runtimeFixture, c runtimeClient, label, amount string) string {
	t.Helper()
	id := captureLead(t, f, c, label, amount)
	runRecordAction(t, c, "lead", id, "lead.mark_contacted", "bf-contact-"+f.phase+"-"+label, map[string]any{})
	runRecordAction(t, c, "lead", id, "lead.qualify", "bf-qualify-"+f.phase+"-"+label, map[string]any{})
	if status := recordDataString(getRecord(t, c, "lead", id), "status"); status != "qualified" {
		t.Fatalf("qualified lead status=%s", status)
	}
	return id
}

func getRecord(t *testing.T, c runtimeClient, objectKey, id string) any {
	t.Helper()
	body, _ := mustRequest(t, c, http.MethodGet, "/records/"+objectKey+"/items/"+url.PathEscape(id), nil, nil, http.StatusOK)
	return body
}

func listRecords(t *testing.T, c runtimeClient, objectKey string, pageSize int, filters map[string]any) []any {
	t.Helper()
	path := fmt.Sprintf("/records/%s?page=1&page_size=%d", objectKey, pageSize)
	if len(filters) != 0 {
		raw, _ := json.Marshal(filters)
		path += "&filters=" + url.QueryEscape(string(raw))
	}
	body, _ := mustRequest(t, c, http.MethodGet, path, nil, nil, http.StatusOK)
	return deepArray(body, "items")
}

func recordID(record any) string { return mapString(record, "id") }

func recordDataString(record any, field string) string {
	if object, ok := record.(map[string]any); ok {
		if data, ok := object["data"].(map[string]any); ok {
			return fmt.Sprint(data[field])
		}
	}
	return ""
}

func createdRecordID(value any, objectKey string) string {
	if object, ok := value.(map[string]any); ok {
		if refs, ok := object["created_records"].([]any); ok {
			for _, raw := range refs {
				if ref, ok := raw.(map[string]any); ok && fmt.Sprint(ref["object_key"]) == objectKey {
					return fmt.Sprint(ref["record_id"])
				}
			}
		}
	}
	return ""
}

func roleIDs(value any) map[string]string {
	result := map[string]string{}
	visitMaps(value, func(item map[string]any) {
		key, id := fmt.Sprint(item["key"]), fmt.Sprint(item["id"])
		if key != "<nil>" && id != "<nil>" {
			result[key] = id
		}
	})
	return result
}

func deepString(value any, key string) string {
	if object, ok := value.(map[string]any); ok {
		if raw, found := object[key]; found {
			if text, ok := raw.(string); ok {
				return text
			}
		}
		for _, child := range object {
			if found := deepString(child, key); found != "" {
				return found
			}
		}
	}
	if values, ok := value.([]any); ok {
		for _, child := range values {
			if found := deepString(child, key); found != "" {
				return found
			}
		}
	}
	return ""
}

func deepHasString(value any, key, wanted string) bool {
	found := false
	visitMaps(value, func(item map[string]any) {
		if fmt.Sprint(item[key]) == wanted {
			found = true
		}
	})
	return found
}

func deepArray(value any, key string) []any {
	if object, ok := value.(map[string]any); ok {
		if values, ok := object[key].([]any); ok {
			return values
		}
		for _, child := range object {
			if values := deepArray(child, key); values != nil {
				return values
			}
		}
	}
	return nil
}

func visitMaps(value any, visit func(map[string]any)) {
	switch typed := value.(type) {
	case map[string]any:
		visit(typed)
		for _, child := range typed {
			visitMaps(child, visit)
		}
	case []any:
		for _, child := range typed {
			visitMaps(child, visit)
		}
	}
}

func mapString(value any, key string) string {
	if object, ok := value.(map[string]any); ok {
		return fmt.Sprint(object[key])
	}
	return ""
}

func compactJSON(value any) string {
	raw, _ := json.Marshal(value)
	if len(raw) > 1000 {
		raw = raw[:1000]
	}
	return string(raw)
}

func containsRecord(items []any, id string) bool {
	for _, item := range items {
		if recordID(item) == id {
			return true
		}
	}
	return false
}

func countEvent(value any, eventType string) int {
	count := 0
	visitMaps(value, func(item map[string]any) {
		if fmt.Sprint(item["event_type"]) == eventType {
			count++
		}
	})
	return count
}

func inboxEvents(t *testing.T, c runtimeClient) any {
	t.Helper()
	body, _ := mustRequest(t, c, http.MethodGet, "/notification/inbox?limit=100", nil, nil, http.StatusOK)
	return body
}

func waitFor(t *testing.T, description string, probe func() bool) {
	t.Helper()
	deadline := time.Now().Add(8 * time.Second)
	for time.Now().Before(deadline) {
		if probe() {
			return
		}
		time.Sleep(100 * time.Millisecond)
	}
	t.Fatalf("timed out waiting for %s", description)
}

