// BF03 / CRM-R06-R09,R13: the highest-risk path runs first. It proves the
// real Workflow/task boundary, unauthorized no-op, atomic terminal facts and
// the requester-owned durable notification.
func TestBF03ApprovalAccepted(t *testing.T) {
	f := fixture(t)
	leadID := qualifyLead(t, f, f.east, "BF03-大额通过-"+f.phase, "100000.00")
	processID, taskID := startApproval(t, f, leadID, "bf03")
	before := getRecord(t, f.director, "lead", leadID)
	status, _, _ := f.eastPeer.request(http.MethodPost, "/workflow/tasks/"+taskID+"/approve", map[string]any{"comment": "越权"}, map[string]string{"Idempotency-Key": "bf03-denied-" + f.phase})
	if status != http.StatusForbidden {
		t.Fatalf("non-assignee approval returned %d, want 403", status)
	}
	afterDenied := getRecord(t, f.director, "lead", leadID)
	if compactJSON(before) != compactJSON(afterDenied) {
		t.Fatalf("denied approval changed lead")
	}
	mustRequest(t, f.director, http.MethodPost, "/workflow/tasks/"+taskID+"/approve", map[string]any{"comment": "同意转化"}, map[string]string{"Idempotency-Key": "bf03-approve-" + f.phase}, http.StatusOK)
	process := waitProcess(t, f.director, processID, "completed")
	if mapString(process, "business_outcome") != "approved" {
		t.Fatalf("approved process outcome mismatch: %s", compactJSON(process))
	}
	lead := getRecord(t, f.director, "lead", leadID)
	if recordDataString(lead, "status") != "converted" {
		t.Fatalf("approved lead did not convert")
	}
	customers := listRecords(t, f.director, "customer", 20, map[string]any{"source_lead_id": leadID})
	requests := listRecords(t, f.director, "lead_conversion_request", 20, map[string]any{"lead_id": leadID})
	if len(customers) != 1 || len(requests) != 1 || recordDataString(requests[0], "status") != "approved" || recordDataString(requests[0], "requester_user_id") != f.east.userID {
		t.Fatalf("approved terminal facts mismatch: customers=%d requests=%s", len(customers), compactJSON(requests))
	}
	waitFor(t, "requester approval notification", func() bool { return countEvent(inboxEvents(t, f.east), "lead.conversion_approved") > 0 })
}

// BF01 / CRM-R01-R05,R11,R13: create and replay one lead, edit and advance it
// as owner, then prove a same-department peer cannot mutate durable state.
func TestBF01LeadLifecycleAndScope(t *testing.T) {
	f := fixture(t)
	label := "BF01-线索生命周期-" + f.phase
	idem := "bf01-create-" + f.phase
	payload := map[string]any{"company_name": label, "contact_name": "甲", "contact_phone": "+8613900000001", "expected_amount": "888.88", "source": "trade_show"}
	first := runObjectAction(t, f.east, "lead", "lead.capture", idem, payload)
	second := runObjectAction(t, f.east, "lead", "lead.capture", idem, payload)
	leadID := createdRecordID(first, "lead")
	if leadID == "" {
		leadID = createdRecordID(second, "lead")
	}
	items := listRecords(t, f.east, "lead", 100, map[string]any{"company_name": label})
	if len(items) != 1 || (leadID != "" && recordID(items[0]) != leadID) {
		t.Fatalf("idempotent capture produced %d matching records", len(items))
	}
	leadID = recordID(items[0])
	runRecordAction(t, f.east, "lead", leadID, "lead.update_details", "bf01-update-"+f.phase, map[string]any{"contact_name": "乙", "contact_phone": "+8613900000002", "expected_amount": "999.99", "source": "referral"})
	runRecordAction(t, f.east, "lead", leadID, "lead.mark_contacted", "bf01-contact-"+f.phase, map[string]any{})
	beforeDenied := getRecord(t, f.east, "lead", leadID)
	status, _, _ := f.eastPeer.request(http.MethodPost, "/records/lead/items/"+leadID+"/actions/lead.qualify", map[string]any{"data": map[string]any{}}, map[string]string{"Idempotency-Key": "bf01-peer-denied-" + f.phase})
	if status != http.StatusForbidden && status != http.StatusNotFound {
		t.Fatalf("same-department non-owner write returned %d, want concealed or denied", status)
	}
	if compactJSON(beforeDenied) != compactJSON(getRecord(t, f.east, "lead", leadID)) {
		t.Fatalf("denied peer write changed durable state")
	}
	runRecordAction(t, f.east, "lead", leadID, "lead.qualify", "bf01-qualify-"+f.phase, map[string]any{})
	qualified := getRecord(t, f.east, "lead", leadID)
	if recordDataString(qualified, "status") != "qualified" || recordDataString(qualified, "contact_name") != "乙" || recordDataString(qualified, "expected_amount") != "999.99" {
		t.Fatalf("owner lifecycle read-back mismatch: %s", compactJSON(qualified))
	}
	status, _, _ = f.east.request(http.MethodPost, "/records/lead/items/"+leadID+"/actions/lead.mark_contacted", map[string]any{"data": map[string]any{}}, map[string]string{"Idempotency-Key": "bf01-illegal-" + f.phase})
	if status != http.StatusConflict && status != http.StatusBadRequest {
		t.Fatalf("illegal state regression returned %d", status)
	}
	if recordDataString(getRecord(t, f.east, "lead", leadID), "status") != "qualified" {
		t.Fatalf("illegal transition changed state")
	}
}

// BF02 / CRM-R06-R08,R10: direct conversion is atomic and replay-safe, and
// the resulting customer is immutable through public business APIs.
func TestBF02DirectConversionIdempotency(t *testing.T) {
	f := fixture(t)
	leadID := qualifyLead(t, f, f.east, "BF02-小额转化-"+f.phase, "99999.99")
	idem := "bf02-convert-" + f.phase
	runRecordAction(t, f.east, "lead", leadID, "lead.convert_direct", idem, map[string]any{})
	runRecordAction(t, f.east, "lead", leadID, "lead.convert_direct", idem, map[string]any{})
	if recordDataString(getRecord(t, f.director, "lead", leadID), "status") != "converted" {
		t.Fatalf("direct conversion did not persist converted state")
	}
	customers := listRecords(t, f.director, "customer", 20, map[string]any{"source_lead_id": leadID})
	if len(customers) != 1 || recordDataString(customers[0], "amount") != "99999.99" {
		t.Fatalf("direct conversion customer mismatch: %s", compactJSON(customers))
	}
	customerID := recordID(customers[0])
	before := getRecord(t, f.director, "customer", customerID)
	status, _, _ := f.director.request(http.MethodPatch, "/records/customer/items/"+customerID, map[string]any{"data": map[string]any{"company_name": "非法修改"}}, map[string]string{"Idempotency-Key": "bf02-customer-update-" + f.phase})
	if status != http.StatusForbidden {
		t.Fatalf("customer update returned %d, want 403", status)
	}
	if compactJSON(before) != compactJSON(getRecord(t, f.director, "customer", customerID)) {
		t.Fatalf("denied customer mutation changed durable state")
	}
}

// BF04 / CRM-R06-R09,R13: rejection persists reason and notification while
// leaving the lead qualified and customer set empty.
func TestBF04ApprovalRejected(t *testing.T) {
	f := fixture(t)
	leadID := qualifyLead(t, f, f.west, "BF04-大额拒绝-"+f.phase, "200000.00")
	processID, taskID := startApprovalFor(t, f, f.west, leadID, "bf04")
	before := getRecord(t, f.director, "lead", leadID)
