// BF08 / CRM-R16: governed Report preparation reaches a completed actor-owned
// Data Exchange job and downloadable CSV, with durable audit/download records.
func TestBF08GovernedCsvExportIsolation(t *testing.T) {
	f := fixture(t)
	auditPayload := map[string]any{"data": map[string]any{"report_key": "lead_detail_export", "requester_user_id": f.director.userID, "provider_job_id": "pending-" + f.phase, "status": "prepared", "row_count": 0, "scope_hash": "runtime-resolves-scope", "reason": "M1 governed export verification"}}
	audit, _ := mustRequest(t, f.director, http.MethodPost, "/records/lead_export_audit", auditPayload, map[string]string{"Idempotency-Key": "bf08-audit-" + f.phase}, http.StatusCreated)
	auditID := recordID(audit)
	if auditID == "" {
		t.Fatalf("export audit creation omitted record ID")
	}
	exportBody := map[string]any{"audit_id": auditID, "scope": map[string]any{"parameters": map[string]any{}, "field_projection": []string{"company_name", "contact_name", "contact_phone", "expected_amount", "responsible_user_id", "source", "status", "status_changed_at"}, "purpose": "M1 sales management review", "freshness": map[string]any{"mode": "realtime"}}}
	headers := map[string]string{"Idempotency-Key": "bf08-export-" + f.phase, "X-Operation-Reason": url.QueryEscape("M1 bounded sales review"), "X-Operation-Confirmation": "confirmed"}
	job, _ := mustRequest(t, f.director, http.MethodPost, "/report/lead_detail_export/exports/lead/prepare", exportBody, headers, http.StatusAccepted)
	jobID := mapString(job, "id")
	if jobID == "" {
		t.Fatalf("export prepare omitted job ID: %s", compactJSON(job))
	}
	status, body, _ := f.east.request(http.MethodPost, "/report/lead_detail_export/exports/lead/prepare", exportBody, map[string]string{"Idempotency-Key": "bf08-sales-denied-" + f.phase, "X-Operation-Reason": url.QueryEscape("unauthorized"), "X-Operation-Confirmation": "confirmed"})
	if status != http.StatusForbidden {
		t.Fatalf("sales export prepare status=%d body=%s", status, compactJSON(body))
	}
	jobPath := "/data-exchange/jobs/" + jobID + "?provider=reports&operation=export"
	var completed any
	waitFor(t, "completed Data Exchange export", func() bool {
		status, candidate, _ := f.director.request(http.MethodGet, jobPath, nil, nil)
		if status == http.StatusOK && mapString(candidate, "status") == "completed" {
			completed = candidate
			return true
		}
		return false
	})
	if mapString(completed, "artifact_id") == "" {
		t.Fatalf("completed export omitted artifact identity")
	}
	status, _, _ = f.east.request(http.MethodGet, jobPath, nil, nil)
	if status != http.StatusForbidden && status != http.StatusNotFound {
		t.Fatalf("foreign job read returned %d", status)
	}
	downloadStatus, download, downloadHeaders := f.director.request(http.MethodGet, "/data-exchange/jobs/"+jobID+"/download?provider=reports&operation=export", nil, nil)
	if downloadStatus != http.StatusOK || !strings.Contains(downloadHeaders.Get("Content-Type"), "text/csv") {
		t.Fatalf("CSV download status=%d content-type=%s", downloadStatus, downloadHeaders.Get("Content-Type"))
	}
	raw, _ := download.([]byte)
	if !strings.Contains(string(raw), "company_name") || len(raw) == 0 {
		t.Fatalf("downloaded CSV lacks expected header")
	}
	status, _, _ = f.east.request(http.MethodGet, "/data-exchange/jobs/"+jobID+"/download?provider=reports&operation=export", nil, nil)
	if status != http.StatusForbidden && status != http.StatusNotFound {
		t.Fatalf("foreign download returned %d", status)
	}
	auditRead := getRecord(t, f.director, "lead_export_audit", auditID)
	downloads := listRecords(t, f.director, "lead_export_download", 20, map[string]any{"provider_job_id": jobID})
	if recordDataString(auditRead, "requester_user_id") != f.director.userID || len(downloads) != 1 || recordDataString(downloads[0], "provider_job_id") != jobID {
		t.Fatalf("export audit/download durable mapping mismatch")
	}
}

