func deepHasString(value any, key, wanted string) bool {
	found := false
	visitMaps(value, func(item map[string]any) {
		if fmt.Sprint(item[key]) == wanted {
			found = true
		}
	})
	return found
}

func deepArray(value any, key string) []any {
	if object, ok := value.(map[string]any); ok {
		if values, ok := object[key].([]any); ok {
			return values
		}
		for _, child := range object {
			if values := deepArray(child, key); values != nil {
				return values
			}
		}
	}
	return nil
}

func visitMaps(value any, visit func(map[string]any)) {
	switch typed := value.(type) {
	case map[string]any:
		visit(typed)
		for _, child := range typed {
			visitMaps(child, visit)
		}
	case []any:
		for _, child := range typed {
			visitMaps(child, visit)
		}
	}
}

func mapString(value any, key string) string {
	if object, ok := value.(map[string]any); ok {
		return fmt.Sprint(object[key])
	}
	return ""
}

func compactJSON(value any) string {
	raw, _ := json.Marshal(value)
	if len(raw) > 1000 {
		raw = raw[:1000]
	}
	return string(raw)
}

func containsRecord(items []any, id string) bool {
	for _, item := range items {
		if recordID(item) == id {
			return true
		}
	}
	return false
}

func countEvent(value any, eventType string) int {
	count := 0
	visitMaps(value, func(item map[string]any) {
		if fmt.Sprint(item["event_type"]) == eventType {
			count++
		}
	})
	return count
}

